pub fn intersperse(numbers: &[i32], delim: i32) -> Vec<i32> {
    let n = numbers.len();
    if n == 0 {
        return Vec::new();
    }

    // For n > 0, result length is exactly 2n - 1.
    let out_len = 2 * n - 1;
    let mut res = Vec::with_capacity(out_len);

    // Push first element, then (delim, element) for each remaining one.
    res.push(numbers[0]);
    for &x in &numbers[1..] {
        res.push(delim);
        res.push(x);
    }

    debug_assert_eq!(res.len(), out_len);
    res
}